This paper considers two nonsmooth problems with convex structures: 1) the convex nonsmooth composite optimization (CNCO) problem
\begin{equation}\label{eq:problem}
    \phi_*:=\min \{\phi(x):=f(x)+h(x): x \in \R^n\},
\end{equation}
where $f,h:\R^n\to \R \cup \{+\infty\}$ are proper lower semi-continuous convex functions such that $\dom h \subset \dom f$;


    Let $\R$ denote the set of real numbers. Let $\R_{++}$ denote the set of positive real numbers. Let $\R^n$ denote the standard $n$-dimensional Euclidean space equipped with inner product and norm denoted by $\left\langle \cdot,\cdot\right\rangle $ and $\|\cdot\|$, respectively. 

    For given $f: \R^n\rightarrow (-\infty,+\infty]$, let $\dom f:=\{x \in \R^n: f (x) <\infty\}$ denote the effective domain of $f$. We say $f$ is proper if $\dom f \ne \emptyset$. A proper function $f: \R^n\rightarrow (-\infty,+\infty]$ is $\mu$-strongly convex for some $\mu > 0$ if for every $x, y \in \dom f$ and $t \in [0,1]$
    \[
    f(t x+(1-t) y)\le t f(x)+(1-t)f(y) - \frac{t(1-t) \mu}{2}\|x-y\|^2.
    \]
Let $\bConv{n}$ denote the set of all proper lower-semicontinuous convex functions.
	For $\varepsilon \ge 0$, the \emph{$\varepsilon$-subdifferential} of $ f $ at $x \in \dom f$ is denoted by
	\begin{equation}\label{def:subdiff}
	    \partial_\varepsilon f (x):=\left\{ s \in\R^n: f(y)\geq f(x)+\left\langle s,y-x\right\rangle -\varepsilon, \forall y\in\R^n\right\}.
	\end{equation}
	We denote the subdifferential of $f$ at $x \in \dom f$ by $\partial f (x)$, which is the set  $\partial_0 f(x)$ by definition.
    For a given subgradient
$f'(x) \in \partial f(x)$, we denote the linearization of convex function $f$ at $x$ by $\ell_f(\cdot;x)$, which is defined as
\begin{equation}\label{linfdef}
\ell_f(\cdot;x):=f(x)+\langle f'(x),\cdot-x\rangle.
\end{equation}
The infimum convolution of proper functions $f_1, f_2: \R^n\rightarrow (-\infty,+\infty]$ is given by
\begin{equation}\label{def:infconv}
    (f_1 \square f_2)(x)
= \min_{u\in \R^n}\{f_1(u) + f_2(x-u)\}.
\end{equation}


In this section, we consider the CNCO problem \eqref{eq:problem}.
More specifically, we assume the following conditions hold:
\begin{itemize}
    \item[(A1)] a subgradient oracle, i.e., a function $f': \dom h \to \R^n$ satisfying $f^{\prime}(x) \in \partial f(x)$ for every $x \in \dom h$, is available;
    \item[(A2)] $\|f'(x)\|\le M$ for every $x\in \dom h$ and some $M>0$;
    \item[(A3)] the set of optimal solutions $X_*$ of problem \eqref{eq:problem} is nonempty.
\end{itemize}
Define the linearization of $f$ at $x\in \dom h$, $\ell_f:\dom h \to \R$ as
\[
\ell_f(\cdot;x):=f(x)+\inner{f'(x)}{\cdot-x}.
\]
Clearly, it follows from (A2) that for every $x, y \in \dom h$,
\begin{equation}\label{ineq:f}
  f(x)-\ell_f(x ; y) \le 2 M\|x-y\|.  
\end{equation}
For a given initial point $\hat x_0 \in \dom h$, we denote its distance to $X_*$ as
\begin{equation}\label{eq:d0}
    d_0:=\left\|x_0^*-\hat x_0\right\|, \quad x_0^*:=\underset{x_* \in X_*}\argmin\{\left\| x_*-\hat x_0\right\|\}.
\end{equation}


The primal-dual subgradient method denoted by PDS$(\hat x_0,\lam)$, where $\hat x_0\in \dom h$ is the initial point and $\lam>0$ is the prox stepsize, recursively computes
\begin{equation}\label{eq:pds}
    s_k = f'(x_{k-1}) \in \partial f(x_{k-1}), \quad \hat x_k = \underset{u\in\R^n}{\argmin}\left\{\ell_f(u;\hat x_{k-1}) + h(u) + \frac{1}{2\lam}\|u-\hat x_{k-1}\|^2 \right\}.
\end{equation}


The PDPB method solves a sequence of proximal subproblems of the form
\begin{equation}\label{eq:phi-lam}
    \min_{u \in \R^n} \left\{\phi^\lam(u) :=\phi(u)+\frac{1}{2 \lambda}\left\|u-\hat x_{k-1}\right\|^2\right\},
\end{equation}
where $\lam$ is the prox stepsize and $\hat x_{k-1}$ is the prox center in the $k$-th proximal subproblem (or cycle). We omit the index $k$ in $\phi^\lam$ since the prox center is always fixed to be $\hat x_{k-1}$ in this subsection.
Each proximal subproblem invokes the PDCP scheme to find an approximate solution. Hence, PDPB can be viewed as a generalization of PDS, which only takes one proximal subgradient step (i.e., \eqref{eq:pds}) to solve every proximal subproblem \eqref{eq:phi-lam}.
The goal of this subsection is to describe the key subroutine PDCP for solving \eqref{eq:phi-lam} and present its primal-dual convergence analysis.


In the rest of this subsection, we consider subproblem \eqref{eq:phi-lam} with fixed prox center $\hat x_{k-1}$. For simplicity, we denote $\hat x_{k-1}$ as $x_0$ from a local perspective within the current cycle, as it is also the initial point of PDCP.  At the $j$-th iteration of PDCP, given some prox stepsize $\lam>0$ and prox center $x_0$, PDCP computes a primal-dual pair $(x_j,s_j)$ as follows
\begin{equation}\label{eq:xj}
    x_j=\underset{u \in \R^n}{\argmin}\left\{\Gamma_j(u) + h(u) +\frac{1}{2 \lam}\|u-x_0\|^2\right\}, \quad s_j \in \partial \Gamma_j(x_j) \cap (-\partial h^\lam(x_j)),  
\end{equation}
where $\Gamma_j$ is a proper, closed and convex function satisfying $\Gamma_j \le f$ for every $j\ge 1$, and
\begin{equation}\label{eq:hlam}
    h^\lam (\cdot) := h(\cdot) + \frac{1}{2\lam}\|\cdot - x_0\|^2.
\end{equation}
Starting from $\Gamma_1(\cdot) = \ell_f(\cdot ; x_0)$, and for every $j\ge 1$,  $\Gamma_{j+1}$ is obtained from the following generic bundle management (GBM), which is motivated by BU given in Subsection~3.1 of \cite{liang2024unified}.


\begin{algorithm}[H]
\caption{Generic Bundle Management, GBM$(\lambda, \tau_j, x_0, x_{j}, \Gamma_j)$}\label{alg:GBM}
\begin{algorithmic}
\REQUIRE $(\lam, \tau_j)\in \R_{++} \times [0,1]$, $(x_0,x_j) \in \R^n \times \R^n$, and $\Gamma_j \in \bConv{n}$ satisfying $\Gamma_j \le f$

\STATE $\bullet$ find a bundle model $\Gamma_{j+1}\in \bConv{n}$ satisfying $\Gamma_{j+1} \le f$ and 
        \begin{equation}\label{def:Gammaj}
	     \Gamma_{j+1}(\cdot) \ge \tau_j \bar \Gamma_j(\cdot) + (1-\tau_j)\ell_f(\cdot; x_j),
	\end{equation}
where $\bar \Gamma_j \in \bConv{n}$ satisfies $\bar \Gamma_j \le f$ and
        \begin{equation}\label{def:bar Gamma}
            \bar \Gamma_j(x_j) = \Gamma_j(x_j), \quad x_j = \underset{u\in \R^n}\argmin \left \{\bar \Gamma_j(u) + h(u) + \frac{1}{2\lam}\|u-x_0\|^2\right\}.
        \end{equation}

\ENSURE $\Gamma_{j+1}$.

\end{algorithmic} 
\end{algorithm}

PDCP computes an auxiliary sequence $\{\tx_j\}$ to determine termination. 
It generated $\tx_j$ such that
\begin{equation}\label{ineq:txj}
    \tilde x_1 = x_1, \quad \mbox{and} \quad \phi^\lam(\tx_{j+1}) \le \tau_j\phi^\lam(\tx_j) + (1-\tau_j)\phi^\lam(x_{j+1}), \, \forall j\ge 1,
\end{equation}
where $\phi^\lam$ is as in \eqref{eq:phi-lam}. 
PDCP also computes
\begin{equation}\label{eq:mj}
    m_j =\underset{u \in \R^n}{\min}\left\{\Gamma_j(u) + h(u) +\frac{1}{2 \lam}\|u-x_0\|^2\right\}, \quad t_j=\phi^\lam \left(\tilde x_j\right)-m_j.
\end{equation}
For given tolerance $\varepsilon>0$, PDCP terminates the current cycle when $t_j \le \varepsilon$.


\begin{algorithm}[H]
\caption{Primal-Dual Cutting-Plane, PDCP$(x_0,\lam,\varepsilon)$}\label{alg:PDCP}
\begin{algorithmic}
\REQUIRE given $x_0\in \dom h$, $\lam>0$, $\varepsilon>0$, set $t_0 = 2\varepsilon$, $\Gamma_1(\cdot)=\ell_f(\cdot;x_0)$, and $j=1$;

\WHILE{$t_{j-1} > \varepsilon$}

\STATE {\bf 1.} compute $(x_j,s_j)$ by \eqref{eq:xj}, choose $\tilde x_j$ as in \eqref{ineq:txj}, and set $t_j$ as in~\eqref{eq:mj};
\STATE {\bf 2.} select $\tau_j \in [0,1]$ and update $\Gamma_{j+1}$ by GBM$(\lambda, \tau_j, x_0, x_{j}, \Gamma_j)$ and $j \leftarrow j+1$;

\ENDWHILE
\ENSURE $(x_{j-1}, \tilde x_{j-1},  s_{j-1})$.

\end{algorithmic} 
\end{algorithm}

Recall the definitions of $d_0$ and $x_0^*$ in \eqref{eq:d0}. Since $x_0^* \in B(\hat x_0, 6d_0)$, which is the ball centered at $\hat x_0$ and with radius $6d_0$, it is easy to see that to solve \eqref{eq:problem}, it suffices to solve
\begin{equation}\label{eq:new}
    \min \left\{\hat \phi(x):=f(x)+\hat h(x): x \in \R^n\right\}
    = \min \left\{\phi(x): x \in Q\right\},
\end{equation}
where $\hat h = h + I_Q$ and $I_Q$ is the indicator function of $Q = B(\hat x_0, 6d_0)$.


\begin{algorithm}[H]
\caption{Primal-Dual Proximal Bundle, PDPB$(\hat x_0,\lam,\bar \varepsilon)$}\label{alg:PDPB}
\begin{algorithmic}
\REQUIRE given $(\hat x_0,\lam,\bar \varepsilon) \in \dom h \times \R_{++} \times \R_{++}$
\FOR{$k=1,2,\cdots$}
\STATE $\bullet$ call oracle $(\hat x_k,\tx_k,s_k) = \text{PDCP}(\hat x_{k-1},\lam, \bar \varepsilon)$ and compute 
\begin{equation}\label{eq:bxk}
    \bar x_k = \frac{1}{k}\sum_{i=1}^{k} \tx_i , \quad \bar s_k = \frac{1}{k}\sum_{i=1}^{k} s_i.
\end{equation}
\ENDFOR
\end{algorithmic} 
\end{algorithm}

Recall from Subsection~\ref{subsec:PDCP} that \eqref{eq:phi-lam} is approximately solved by invoking PDCP. The (global) iteration indices in PDCP are regarded as the $k$-th cycle, denoted by ${\cal C}_k=\left\{i_k, \ldots, j_k\right\}$, where $j_k$ is the last iteration index of the $k$-th call to PDCP, $j_0=0$, and $i_k = j_{k-1}+1$.
Hence, for the $j_k$-th iteration of PDCP, we have
\begin{equation}\label{eq:translate}
    \hat x_k = x_{j_k}, \quad \tilde x_k = \tilde x_{j_k}, \quad s_k = s_{j_k}, \quad \Gamma_k  = \Gamma_{j_k}, \quad m_k = m_{j_k},
\end{equation}
and \eqref{eq:xj} becomes
\begin{equation}\label{eq:xk}
    \hat x_k=\underset{u \in \R^n}{\argmin}\left\{\Gamma_k(u) + h(u) +\frac{1}{2 \lambda}\left\|u-\hat x_{k-1}\right\|^2\right\}, \quad s_k \in \partial \Gamma_k(\hat x_k) \cap (-\partial h^\lam(\hat x_k)).
\end{equation}


Recall the definitions of $d_0$ and $x_0^*$ in \eqref{eq:d0}. Since $x_0^* \in B(\hat x_0, 4d_0)$, which is the ball centered at $\hat x_0$ and with radius $4d_0$, it is easy to see that to solve \eqref{eq:problem}, it suffices to solve
\begin{equation}\label{eq:constrained}
    \min \left\{\hat \phi(x):=f(x)+\hat h(x): x \in \R^n\right\}
    = \min \left\{\phi(x): x \in Q\right\},
\end{equation}
where $\hat h = h + I_Q$ and $I_Q$ is the indicator function of $Q = B(\hat x_0, 4d_0)$.
Hence, it is convenient to consider a slightly modified version of PDS$(\hat x_0,\lam)$ with $h$ replaced by $\hat h$ in \eqref{eq:pds}, denoted by MPDS$(\hat x_0,\lam)$, i.e.,
\begin{equation}\label{eq:pds-1}
    s_k = f'(\hat x_{k-1}), \quad \hat x_k = \underset{u\in\R^n}{\argmin}\left\{\ell_f(u;\hat x_{k-1}) + \hat h(u) + \frac{1}{2\lam}\|u-\hat x_{k-1}\|^2 \right\}.
\end{equation}

