\begin{theorem}
    Given $(\hat x_0,\bar \varepsilon) \in \R^n \times \R_{++}$, assuming that $\lam$ satisfies
    \begin{equation}\label{ineq:lam}
        \frac{\sqrt{\bar \varepsilon d_0}}{M^{3/2}} \le \lam \le \frac{2d_0^2}{\bar \varepsilon},
    \end{equation}
    then the total iteration-complexity of PDPB$(\hat x_0,\lam,\bar \varepsilon)$ to find $(\bar x_k,\bar s_k)$ satisfying \eqref{ineq:pd} is
    \begin{equation}\label{cmplx:PDPB}
        {\cal O}\left( \frac{M^2 d_0^2}{\bar \varepsilon^2} + 1\right).
    \end{equation}
\end{theorem}

