\begin{lemma}\label{lem:Gamma}
For every $j \ge 1$, there exists $\bar \Gamma_j \in \bConv{n}$ such that for every $u\in \R^n$,
\begin{equation}\label{ineq:bGammaj}
    \bar{\Gamma}_j(u) + h^\lam(u) \ge m_j + \frac{1}{2\lam}\|u-x_j\|^2.
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:inner}
Considering Algorithm \ref{alg:PDCP} with $\tau_j = j/(j+2)$, then for every $j \ge 1$, we have
\begin{equation}\label{ineq:tj}
    t_j\le \frac{2t_1}{j(j+1)} + \frac{16\lam M^2}{j+1},
\end{equation}
where $t_j$ is as in \eqref{eq:mj}.
Moreover, the number of iterations for PDCP to obtain $t_j \le \varepsilon$ is at most
\[
{\cal O}\left(\frac{\sqrt{t_1}}{\sqrt{\varepsilon}} + \frac{\lam M^2}{\varepsilon} + 1\right).
\]
\end{proposition}

\begin{proof}
We first note that for every $j\ge 1$, $\tau_j=A_j/A_{j+1}$ where $A_{j+1}=A_j+j+1$ and $A_0=0$, i.e., $A_j=j(j+1)/2$ for every $j\ge 0$.
It follows from this observation, the definition of $m_j$ in \eqref{eq:mj}, and relation \eqref{def:Gammaj} that
\begin{align*}
    A_{j+1}m_{j+1} & \stackrel{\eqref{eq:mj}}{=} A_{j+1}(\Gamma_{j+1}+h^\lam)(x_{j+1}) \\
    &\stackrel{\eqref{def:Gammaj}}{\ge} A_j \left[(\bar \Gamma_j+ h^\lam)(x_{j+1}) \right] + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1})\right].
\end{align*}
Applying Lemma~\ref{lem:Gamma} in the above inequality and using \eqref{ineq:f}, we have
\begin{align*}
    A_{j+1}m_{j+1} 
    &\stackrel{\eqref{ineq:bGammaj}}{\ge} A_j \left[ m_j+\frac{1}{2\lam}\|x_{j+1} - x_j\|^2 \right] + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1})\right] \\
    &= A_j m_j + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1}) + \frac{A_j}{2\lam (j+1)}\|x_{j+1} - x_j\|^2 \right] \\
    &\stackrel{\eqref{ineq:f}}{\ge} A_j m_j + (j+1)\left[\phi^\lam(x_{j+1}) - 2M\|x_{j+1}-x_j\| + \frac{A_j}{2\lam (j+1)}\|x_{j+1} - x_j\|^2 \right] \\
    &\ge A_j m_j + (j+1)\phi^\lam(x_{j+1}) - \frac{2\lam M^2 (j+1)^2}{A_j}
\end{align*}
where the last inequality is due to the Young's inequality $a^2+b^2\ge 2ab$.
It follows from the fact that $A_j=j(j+1)/2$ that for every $j\ge 1$,
\[
    A_{j+1}m_{j+1} \ge A_j m_j + (j+1)\phi^\lam(x_{j+1}) - 8\lam M^2.
\]
Replacing the index $j$ in the above inequality by $i$, summing the resulting inequality from $i=1$ to $j-1$, and using the definition of $t_j$ in \eqref{eq:mj} and the fact that $\tx_1=x_1$, we obtain
\begin{align*}
    A_j m_j
    &\ge A_1 m_1 + 2 \phi^\lam(x_2) + \dots + j\phi^\lam(x_j) - 8\lam M^2 (j-1) \\
    &\stackrel{\eqref{eq:mj}}{=} -A_1 t_1 + A_1 \phi^\lam(x_1) + 2 \phi^\lam(x_2) + \dots + j\phi^\lam(x_j) - 8\lam M^2 (j-1) \\
    &\stackrel{\eqref{ineq:txj}}{\ge} -A_1 t_1 + A_j \phi^\lam(\tx_j) - 8\lam M^2 (j-1),
\end{align*}
where the last inequality follows from \eqref{ineq:txj} and the fact that $A_j=A_{j-1}+j$.
Rearranging the terms and using the definition of $t_j$ in \eqref{eq:mj} again, we have
\begin{equation}\label{ineq:Aj-tj}
    A_j t_j \le A_1 t_1 + 8\lam M^2 (j-1).
\end{equation}
Hence, \eqref{ineq:tj} follows from the fact that $A_j=j(j+1)/2$.
Finally, the complexity bound immediately follows from \eqref{ineq:tj}.
\end{proof}

\begin{lemma}\label{ser-lemma1}
    The following statements hold for every $k \ge 1$:
    \begin{enumerate}
        \item [(a)] $\Gamma_k \le f$ and $f^*\le \Gamma_k^*$;
        \item [(b)] $s_k \in \partial \Gamma_k(\hat x_k)$ and $g_k \in \partial h(\hat x_k)$ where $g_k = - s_k + (\hat x_{k-1}-\hat x_k)/\lam$;
        \item [(c)] $\phi^\lam(\tilde x_k) \le \bar \varepsilon + m_k = \bar \varepsilon + (\Gamma_k + h)(\hat x_k) + \|\hat x_k - \hat x_{k-1}\|^2/(2\lam)$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    (a) It follows from the facts that $\Gamma_j \le f$ for every $j\ge 1$ and $\Gamma_k=\Gamma_{j_k}$ that the first inequality holds. The second one immediately follows from the first one and the definition of the conjugate function.

    (b) This statement follows from \eqref{eq:xk} and the definitions in \eqref{eq:translate}.

    (c) This statement follows from the termination criterion of the $k$-th cycle, that is, $t_{j_k}\le \bar \varepsilon$, and the definitions in \eqref{eq:mj} and \eqref{eq:translate}.
\end{proof}

\begin{proposition}\label{prop:pd-key}
For every $k \ge 1$, we have
\begin{equation}\label{ineq:conjugate}
    \phi(\bar{x}_k) + f^*(\bar s_k) + \hat h ^*(-\bar s_k) \le \bar \varepsilon + \frac{18 d_0^2}{\lam k}.
\end{equation}
where $\bar x_k$ and $\bar s_k$ are as in \eqref{eq:bxk}.
\end{proposition}

\begin{lemma}\label{lem:bound}
    Given $(\hat x_0,\bar \varepsilon) \in \R^n \times \R_{++}$, if $\lam \le 2d_0^2/\bar \varepsilon$ and $k \le 2d_0^2/(\lam \bar \varepsilon)$, then the sequences $\{\hat x_k\}$ and $\{\tx_k\}$ generated by PDPB$(\hat x_0,\lam, \bar \varepsilon)$ satisfy
    \begin{equation}\label{incl:xk}
        \hat x_k \in Q, \quad \tx_k \in Q.
    \end{equation}
\end{lemma}

\begin{proposition}\label{prop:pdpb}
    Given $(\hat x_0,\bar \varepsilon) \in \R^n \times \R_{++}$, if $\lam \le 2d_0^2/\bar \varepsilon$, then the number of iterations for PDPB$(\hat x_0,\lam, \bar \varepsilon)$ to generate $(\bar x_k, \bar s_k)$ satisfying 
    \begin{equation}\label{ineq:pd}
        \hat \phi(\bar x_k) + f^*(\bar s_k) + \hat h^*(-\bar s_k) \le 10\bar \varepsilon
    \end{equation}
    is at most $2 d_0^2/(\lam \bar \varepsilon)$.
\end{proposition}

\begin{lemma}\label{lem:t1}
For $k \le 2d_0^2/(\lam \bar \varepsilon)$, we have
\begin{equation}\label{ineq:t1}
    t_{i_k} \le \bar{t}:= 4M(3d_0 + \lam M),
\end{equation}
where $i_k$ is the first iteration index in the cycle ${\cal C}_k$.
\end{lemma}

\begin{proof}
    In view of Proposition \ref{prop:pdpb}, PDPB takes 
    \begin{equation}\label{cmplx:outer}
        {\cal O}\left(\frac{d_0^2}{\lam \bar \varepsilon}+1\right)
    \end{equation}
    cycles to find $(\bar x_k,\bar s_k)$ satisfying \eqref{ineq:pd}.
    It follows from Proposition \ref{prop:inner} and Lemma \ref{lem:t1} that for every cycle in PDPB before termination, the number of iterations in the cycle is 
    \[
    {\cal O}\left(\frac{\sqrt{Md_0 + \lam M^2}}{\sqrt{\bar \varepsilon}} + \frac{\lam M^2}{\bar \varepsilon} + 1\right)=
    {\cal O}\left(\frac{\sqrt{Md_0}}{\sqrt{\bar \varepsilon}} + \frac{\lam M^2}{\bar \varepsilon} + 1\right),
    \]
    which together with the assumption that $\sqrt{\bar \varepsilon d_0}/M^{3/2} \le \lam$ becomes
    \begin{equation}\label{cmplx:inner}
        {\cal O}\left(\frac{\lam M^2}{\bar \varepsilon} + 1\right).
    \end{equation}
    Combining \eqref{cmplx:outer} and \eqref{cmplx:inner}, and using \eqref{ineq:lam}, we conclude that \eqref{cmplx:PDPB} holds.
\end{proof}

\begin{lemma}\label{pds-lemma1}
Given $\hat x_0 \in \R^n$, for every $k \ge 1$ and $u \in \dom \hat h$, the sequence $\{\hat x_k\}$ generated by MPDS$(\hat x_0,\lam)$ satisfies
\begin{equation}\label{ineq:hat-phi-recur}
    \hat \phi(\hat x_k) - \ell_f(u;\hat x_{k-1}) - \hat h(u) \le 2\lam M^2 + \frac{1}{2\lam}\|u- \hat x_{k-1}\|^2 - \frac1{2\lam}\|u - \hat x_k\|^2.
\end{equation}
\end{lemma}

\begin{proof}
Noticing that the objective function in \eqref{eq:pds-1} is $\lam^{-1}$-strongly convex, it then follows from Theorem 5.25(b) of \cite{Beck2017} that for every $u \in \dom \hat h$,
\begin{equation}\label{ineq:ell-h-mk}
    \ell_f(u;\hat x_{k-1}) + \hat h(u) + \frac1{2\lam}\|u-\hat x_{k-1}\|^2 \ge m_k + \frac{1}{2\lam} \|u-\hat x_k\|^2,
\end{equation}
where $m_k = \ell_f(\hat x_k;\hat x_{k-1}) + \hat h(\hat x_k) + \|\hat x_k-\hat x_{k-1}\|^2/(2\lam)$.
Using \eqref{ineq:f} with $(x,y)=(\hat x_k,\hat x_{k-1})$, we have
\[
    \hat \phi(\hat x_k) - m_k = f(\hat x_k) - \ell_f(\hat x_k;\hat x_{k-1}) \stackrel{\eqref{ineq:f}}{\le} 2M\|\hat x_k - \hat x_{k-1}\| - \frac1{2\lam}\|\hat x_k-\hat x_{k-1}\|^2 \le 2\lam M^2,
\]
where the last inequality is due to Young's inequality $a^2+b^2\ge 2ab$.
Hence, \eqref{ineq:hat-phi-recur} follows from combining the above inequality and \eqref{ineq:ell-h-mk}.
\end{proof}

