This paper considers two nonsmooth problems with convex structures: 1) the convex nonsmooth composite optimization (CNCO) problem
\begin{equation}\label{eq:problem}
    \phi_*:=\min \{\phi(x):=f(x)+h(x): x \in \R^n\},
\end{equation}
where $f,h:\R^n\to \R \cup \{+\infty\}$ are proper lower semi-continuous convex functions such that $\dom h \subset \dom f$;

	For $\varepsilon \ge 0$, the \emph{$\varepsilon$-subdifferential} of $ f $ at $x \in \dom f$ is denoted by
	\begin{equation}\label{def:subdiff}
	    \partial_\varepsilon f (x):=\left\{ s \in\R^n: f(y)\geq f(x)+\left\langle s,y-x\right\rangle -\varepsilon, \forall y\in\R^n\right\}.
	\end{equation}
	We denote the subdifferential of $f$ at $x \in \dom f$ by $\partial f (x)$, which is the set  $\partial_0 f(x)$ by definition.
    For a given subgradient
$f'(x) \in \partial f(x)$, we denote the linearization of convex function $f$ at $x$ by $\ell_f(\cdot;x)$, which is defined as
\begin{equation}\label{linfdef}
\ell_f(\cdot;x):=f(x)+\langle f'(x),\cdot-x\rangle.
\end{equation}

The infimum convolution of proper functions $f_1, f_2: \R^n\rightarrow (-\infty,+\infty]$ is given by
\begin{equation}\label{def:infconv}
    (f_1 \square f_2)(x)
= \min_{u\in \R^n}\{f_1(u) + f_2(x-u)\}.
\end{equation}

In this section, we consider the CNCO problem \eqref{eq:problem}.
More specifically, we assume the following conditions hold:
\begin{itemize}
    \item[(A1)] a subgradient oracle, i.e., a function $f': \dom h \to \R^n$ satisfying $f^{\prime}(x) \in \partial f(x)$ for every $x \in \dom h$, is available;
    \item[(A2)] $\|f'(x)\|\le M$ for every $x\in \dom h$ and some $M>0$;
    \item[(A3)] the set of optimal solutions $X_*$ of problem \eqref{eq:problem} is nonempty.
\end{itemize}

For a given initial point $\hat x_0 \in \dom h$, we denote its distance to $X_*$ as
\begin{equation}\label{eq:d0}
    d_0:=\left\|x_0^*-\hat x_0\right\|, \quad x_0^*:=\underset{x_* \in X_*}\argmin\{\left\| x_*-\hat x_0\right\|\}.
\end{equation}

The primal-dual subgradient method denoted by PDS$(\hat x_0,\lam)$, where $\hat x_0\in \dom h$ is the initial point and $\lam>0$ is the prox stepsize, recursively computes
\begin{equation}\label{eq:pds}
    s_k = f'(x_{k-1}) \in \partial f(x_{k-1}), \quad \hat x_k = \underset{u\in\R^n}{\argmin}\left\{\ell_f(u;\hat x_{k-1}) + h(u) + \frac{1}{2\lam}\|u-\hat x_{k-1}\|^2 \right\}.
\end{equation}

In the rest of this subsection, we consider subproblem \eqref{eq:phi-lam} with fixed prox center $\hat x_{k-1}$. For simplicity, we denote $\hat x_{k-1}$ as $x_0$ from a local perspective within the current cycle, as it is also the initial point of PDCP.  At the $j$-th iteration of PDCP, given some prox stepsize $\lam>0$ and prox center $x_0$, PDCP computes a primal-dual pair $(x_j,s_j)$ as follows
\begin{equation}\label{eq:xj}
    x_j=\underset{u \in \R^n}{\argmin}\left\{\Gamma_j(u) + h(u) +\frac{1}{2 \lam}\|u-x_0\|^2\right\}, \quad s_j \in \partial \Gamma_j(x_j) \cap (-\partial h^\lam(x_j)),  
\end{equation}
where $\Gamma_j$ is a proper, closed and convex function satisfying $\Gamma_j \le f$ for every $j\ge 1$, and
\begin{equation}\label{eq:hlam}
    h^\lam (\cdot) := h(\cdot) + \frac{1}{2\lam}\|\cdot - x_0\|^2.
\end{equation}
Starting from $\Gamma_1(\cdot) = \ell_f(\cdot ; x_0)$, and for every $j\ge 1$,  $\Gamma_{j+1}$ is obtained from the following generic bundle management (GBM), which is motivated by BU given in Subsection~3.1 of \cite{liang2024unified}.

\begin{algorithm}[H]
\caption{Generic Bundle Management, GBM$(\lambda, \tau_j, x_0, x_{j}, \Gamma_j)$}\label{alg:GBM}
\begin{algorithmic}
\REQUIRE $(\lam, \tau_j)\in \R_{++} \times [0,1]$, $(x_0,x_j) \in \R^n \times \R^n$, and $\Gamma_j \in \bConv{n}$ satisfying $\Gamma_j \le f$

\STATE $\bullet$ find a bundle model $\Gamma_{j+1}\in \bConv{n}$ satisfying $\Gamma_{j+1} \le f$ and 
        \begin{equation}\label{def:Gammaj}
	     \Gamma_{j+1}(\cdot) \ge \tau_j \bar \Gamma_j(\cdot) + (1-\tau_j)\ell_f(\cdot; x_j),
	\end{equation}
where $\bar \Gamma_j \in \bConv{n}$ satisfies $\bar \Gamma_j \le f$ and
        \begin{equation}\label{def:bar Gamma}
            \bar \Gamma_j(x_j) = \Gamma_j(x_j), \quad x_j = \underset{u\in \R^n}\argmin \left \{\bar \Gamma_j(u) + h(u) + \frac{1}{2\lam}\|u-x_0\|^2\right\}.
        \end{equation}

\ENSURE $\Gamma_{j+1}$.

\end{algorithmic} 
\end{algorithm}

PDCP computes an auxiliary sequence $\{\tx_j\}$ to determine termination. 
It generated $\tx_j$ such that
\begin{equation}\label{ineq:txj}
    \tilde x_1 = x_1, \quad \mbox{and} \quad \phi^\lam(\tx_{j+1}) \le \tau_j\phi^\lam(\tx_j) + (1-\tau_j)\phi^\lam(x_{j+1}), \, \forall j\ge 1,
\end{equation}
where $\phi^\lam$ is as in \eqref{eq:phi-lam}. 
PDCP also computes
\begin{equation}\label{eq:mj}
    m_j =\underset{u \in \R^n}{\min}\left\{\Gamma_j(u) + h(u) +\frac{1}{2 \lam}\|u-x_0\|^2\right\}, \quad t_j=\phi^\lam \left(\tilde x_j\right)-m_j.
\end{equation}
For given tolerance $\varepsilon>0$, PDCP terminates the current cycle when $t_j \le \varepsilon$.

\begin{algorithm}[H]
\caption{Primal-Dual Cutting-Plane, PDCP$(x_0,\lam,\varepsilon)$}\label{alg:PDCP}
\begin{algorithmic}
\REQUIRE given $x_0\in \dom h$, $\lam>0$, $\varepsilon>0$, set $t_0 = 2\varepsilon$, $\Gamma_1(\cdot)=\ell_f(\cdot;x_0)$, and $j=1$;

\WHILE{$t_{j-1} > \varepsilon$}

\STATE {\bf 1.} compute $(x_j,s_j)$ by \eqref{eq:xj}, choose $\tilde x_j$ as in \eqref{ineq:txj}, and set $t_j$ as in~\eqref{eq:mj};
\STATE {\bf 2.} select $\tau_j \in [0,1]$ and update $\Gamma_{j+1}$ by GBM$(\lambda, \tau_j, x_0, x_{j}, \Gamma_j)$ and $j \leftarrow j+1$;

\ENDWHILE
\ENSURE $(x_{j-1}, \tilde x_{j-1},  s_{j-1})$.

\end{algorithmic} 
\end{algorithm}

Recall the definitions of $d_0$ and $x_0^*$ in \eqref{eq:d0}. Since $x_0^* \in B(\hat x_0, 6d_0)$, which is the ball centered at $\hat x_0$ and with radius $6d_0$, it is easy to see that to solve \eqref{eq:problem}, it suffices to solve
\begin{equation}\label{eq:new}
    \min \left\{\hat \phi(x):=f(x)+\hat h(x): x \in \R^n\right\}
    = \min \left\{\phi(x): x \in Q\right\},
\end{equation}
where $\hat h = h + I_Q$ and $I_Q$ is the indicator function of $Q = B(\hat x_0, 6d_0)$.

\begin{algorithm}[H]
\caption{Primal-Dual Proximal Bundle, PDPB$(\hat x_0,\lam,\bar \varepsilon)$}\label{alg:PDPB}
\begin{algorithmic}
\REQUIRE given $(\hat x_0,\lam,\bar \varepsilon) \in \dom h \times \R_{++} \times \R_{++}$
\FOR{$k=1,2,\cdots$}
\STATE $\bullet$ call oracle $(\hat x_k,\tx_k,s_k) = \text{PDCP}(\hat x_{k-1},\lam, \bar \varepsilon)$ and compute 
\begin{equation}\label{eq:bxk}
    \bar x_k = \frac{1}{k}\sum_{i=1}^{k} \tx_i , \quad \bar s_k = \frac{1}{k}\sum_{i=1}^{k} s_i.
\end{equation}
\ENDFOR
\end{algorithmic} 
\end{algorithm}

Recall from Subsection~\ref{subsec:PDCP} that \eqref{eq:phi-lam} is approximately solved by invoking PDCP. The (global) iteration indices in PDCP are regarded as the $k$-th cycle, denoted by ${\cal C}_k=\left\{i_k, \ldots, j_k\right\}$, where $j_k$ is the last iteration index of the $k$-th call to PDCP, $j_0=0$, and $i_k = j_{k-1}+1$.
Hence, for the $j_k$-th iteration of PDCP, we have
\begin{equation}\label{eq:translate}
    \hat x_k = x_{j_k}, \quad \tilde x_k = \tilde x_{j_k}, \quad s_k = s_{j_k}, \quad \Gamma_k  = \Gamma_{j_k}, \quad m_k = m_{j_k},
\end{equation}
and \eqref{eq:xj} becomes
\begin{equation}\label{eq:xk}
    \hat x_k=\underset{u \in \R^n}{\argmin}\left\{\Gamma_k(u) + h(u) +\frac{1}{2 \lambda}\left\|u-\hat x_{k-1}\right\|^2\right\}, \quad s_k \in \partial \Gamma_k(\hat x_k) \cap (-\partial h^\lam(\hat x_k)).
\end{equation}

Recall the definitions of $d_0$ and $x_0^*$ in \eqref{eq:d0}. Since $x_0^* \in B(\hat x_0, 4d_0)$, which is the ball centered at $\hat x_0$ and with radius $4d_0$, it is easy to see that to solve \eqref{eq:problem}, it suffices to solve
\begin{equation}\label{eq:constrained}
    \min \left\{\hat \phi(x):=f(x)+\hat h(x): x \in \R^n\right\}
    = \min \left\{\phi(x): x \in Q\right\},
\end{equation}
where $\hat h = h + I_Q$ and $I_Q$ is the indicator function of $Q = B(\hat x_0, 4d_0)$.

Hence, it is convenient to consider a slightly modified version of PDS$(\hat x_0,\lam)$ with $h$ replaced by $\hat h$ in \eqref{eq:pds}, denoted by MPDS$(\hat x_0,\lam)$, i.e.,
\begin{equation}\label{eq:pds-1}
    s_k = f'(\hat x_{k-1}), \quad \hat x_k = \underset{u\in\R^n}{\argmin}\left\{\ell_f(u;\hat x_{k-1}) + \hat h(u) + \frac{1}{2\lam}\|u-\hat x_{k-1}\|^2 \right\}.
\end{equation}

\begin{lemma}\label{lem:Gamma}
For every $j \ge 1$, there exists $\bar \Gamma_j \in \bConv{n}$ such that for every $u\in \R^n$,
\begin{equation}\label{ineq:bGammaj}
    \bar{\Gamma}_j(u) + h^\lam(u) \ge m_j + \frac{1}{2\lam}\|u-x_j\|^2.
\end{equation}
\end{lemma}

\begin{proposition}\label{prop:inner}
Considering Algorithm \ref{alg:PDCP} with $\tau_j = j/(j+2)$, then for every $j \ge 1$, we have
\begin{equation}\label{ineq:tj}
    t_j\le \frac{2t_1}{j(j+1)} + \frac{16\lam M^2}{j+1},
\end{equation}
where $t_j$ is as in \eqref{eq:mj}.
Moreover, the number of iterations for PDCP to obtain $t_j \le \varepsilon$ is at most
\[
{\cal O}\left(\frac{\sqrt{t_1}}{\sqrt{\varepsilon}} + \frac{\lam M^2}{\varepsilon} + 1\right).
\]
\end{proposition}

\begin{proof}
We first note that for every $j\ge 1$, $\tau_j=A_j/A_{j+1}$ where $A_{j+1}=A_j+j+1$ and $A_0=0$, i.e., $A_j=j(j+1)/2$ for every $j\ge 0$.
It follows from this observation, the definition of $m_j$ in \eqref{eq:mj}, and relation \eqref{def:Gammaj} that
\begin{align*}
    A_{j+1}m_{j+1} & \stackrel{\eqref{eq:mj}}{=} A_{j+1}(\Gamma_{j+1}+h^\lam)(x_{j+1}) \\
    &\stackrel{\eqref{def:Gammaj}}{\ge} A_j \left[(\bar \Gamma_j+ h^\lam)(x_{j+1}) \right] + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1})\right].
\end{align*}
Applying Lemma~\ref{lem:Gamma} in the above inequality and using \eqref{ineq:f}, we have
\begin{align*}
    A_{j+1}m_{j+1} 
    &\stackrel{\eqref{ineq:bGammaj}}{\ge} A_j \left[ m_j+\frac{1}{2\lam}\|x_{j+1} - x_j\|^2 \right] + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1})\right] \\
    &= A_j m_j + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1}) + \frac{A_j}{2\lam (j+1)}\|x_{j+1} - x_j\|^2 \right] \\
    &\stackrel{\eqref{ineq:f}}{\ge} A_j m_j + (j+1)\left[\phi^\lam(x_{j+1}) - 2M\|x_{j+1}-x_j\| + \frac{A_j}{2\lam (j+1)}\|x_{j+1} - x_j\|^2 \right] \\
    &\ge A_j m_j + (j+1)\phi^\lam(x_{j+1}) - \frac{2\lam M^2 (j+1)^2}{A_j}
\end{align*}
where the last inequality is due to the Young's inequality $a^2+b^2\ge 2ab$.
It follows from the fact that $A_j=j(j+1)/2$ that for every $j\ge 1$,
\[
    A_{j+1}m_{j+1} \ge A_j m_j + (j+1)\phi^\lam(x_{j+1}) - 8\lam M^2.
\]
Replacing the index $j$ in the above inequality by $i$, summing the resulting inequality from $i=1$ to $j-1$, and using the definition of $t_j$ in \eqref{eq:mj} and the fact that $\tx_1=x_1$, we obtain
\begin{align*}
    A_j m_j
    &\ge A_1 m_1 + 2 \phi^\lam(x_2) + \dots + j\phi^\lam(x_j) - 8\lam M^2 (j-1) \\
    &\stackrel{\eqref{eq:mj}}{=} -A_1 t_1 + A_1 \phi^\lam(x_1) + 2 \phi^\lam(x_2) + \dots + j\phi^\lam(x_j) - 8\lam M^2 (j-1) \\
    &\stackrel{\eqref{ineq:txj}}{\ge} -A_1 t_1 + A_j \phi^\lam(\tx_j) - 8\lam M^2 (j-1),
\end{align*}
where the last inequality follows from \eqref{ineq:txj} and the fact that $A_j=A_{j-1}+j$.
Rearranging the terms and using the definition of $t_j$ in \eqref{eq:mj} again, we have
\begin{equation}\label{ineq:Aj-tj}
    A_j t_j \le A_1 t_1 + 8\lam M^2 (j-1).
\end{equation}
Hence, \eqref{ineq:tj} follows from the fact that $A_j=j(j+1)/2$.
Finally, the complexity bound immediately follows from \eqref{ineq:tj}.
\end{proof}

We first note that for every $j\ge 1$, $\tau_j=A_j/A_{j+1}$ where $A_{j+1}=A_j+j+1$ and $A_0=0$, i.e., $A_j=j(j+1)/2$ for every $j\ge 0$.
It follows from this observation, the definition of $m_j$ in \eqref{eq:mj}, and relation \eqref{def:Gammaj} that
\begin{align*}
    A_{j+1}m_{j+1} & \stackrel{\eqref{eq:mj}}{=} A_{j+1}(\Gamma_{j+1}+h^\lam)(x_{j+1}) \\
    &\stackrel{\eqref{def:Gammaj}}{\ge} A_j \left[(\bar \Gamma_j+ h^\lam)(x_{j+1}) \right] + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1})\right].
\end{align*}

Applying Lemma~\ref{lem:Gamma} in the above inequality and using \eqref{ineq:f}, we have
\begin{align*}
    A_{j+1}m_{j+1} 
    &\stackrel{\eqref{ineq:bGammaj}}{\ge} A_j \left[ m_j+\frac{1}{2\lam}\|x_{j+1} - x_j\|^2 \right] + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1})\right] \\
    &= A_j m_j + (j+1)\left[\ell_f(x_{j+1};x_j) + h^\lam(x_{j+1}) + \frac{A_j}{2\lam (j+1)}\|x_{j+1} - x_j\|^2 \right] \\
    &\stackrel{\eqref{ineq:f}}{\ge} A_j m_j + (j+1)\left[\phi^\lam(x_{j+1}) - 2M\|x_{j+1}-x_j\| + \frac{A_j}{2\lam (j+1)}\|x_{j+1} - x_j\|^2 \right] \\
    &\ge A_j m_j + (j+1)\phi^\lam(x_{j+1}) - \frac{2\lam M^2 (j+1)^2}{A_j}
\end{align*}
where the last inequality is due to the Young's inequality $a^2+b^2\ge 2ab$.

Rearranging the terms and using the definition of $t_j$ in \eqref{eq:mj} again, we have
\begin{equation}\label{ineq:Aj-tj}
    A_j t_j \le A_1 t_1 + 8\lam M^2 (j-1).
\end{equation}
Hence, \eqref{ineq:tj} follows from the fact that $A_j=j(j+1)/2$.
Finally, the complexity bound immediately follows from \eqref{ineq:tj}.

\begin{lemma}\label{ser-lemma1}
    The following statements hold for every $k \ge 1$:
    \begin{enumerate}
        \item [(a)] $\Gamma_k \le f$ and $f^*\le \Gamma_k^*$;
        \item [(b)] $s_k \in \partial \Gamma_k(\hat x_k)$ and $g_k \in \partial h(\hat x_k)$ where $g_k = - s_k + (\hat x_{k-1}-\hat x_k)/\lam$;
        \item [(c)] $\phi^\lam(\tilde x_k) \le \bar \varepsilon + m_k = \bar \varepsilon + (\Gamma_k + h)(\hat x_k) + \|\hat x_k - \hat x_{k-1}\|^2/(2\lam)$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    (a) It follows from the facts that $\Gamma_j \le f$ for every $j\ge 1$ and $\Gamma_k=\Gamma_{j_k}$ that the first inequality holds. The second one immediately follows from the first one and the definition of the conjugate function.

    (b) This statement follows from \eqref{eq:xk} and the definitions in \eqref{eq:translate}.

    (c) This statement follows from the termination criterion of the $k$-th cycle, that is, $t_{j_k}\le \bar \varepsilon$, and the definitions in \eqref{eq:mj} and \eqref{eq:translate}.
\end{proof}

\begin{proposition}\label{prop:pd-key}
For every $k \ge 1$, we have
\begin{equation}\label{ineq:conjugate}
    \phi(\bar{x}_k) + f^*(\bar s_k) + \hat h ^*(-\bar s_k) \le \bar \varepsilon + \frac{18 d_0^2}{\lam k}.
\end{equation}
where $\bar x_k$ and $\bar s_k$ are as in \eqref{eq:bxk}.
\end{proposition}

Using the above identity and Lemma \ref{ser-lemma1}(a) and (c), we have for every $k \ge 1$,
\begin{align*}
& \phi(\tilde x_k) + f^*(s_k) +  {h}^*(g_k) \le \phi(\tilde x_k) + \Gamma_k^*(s_k) +  {h}^*(g_k) \\
\le & \bar \varepsilon +(\Gamma_k + h)(\hat x_k) + \frac{1}{2\lam}\|\hat x_k-\hat x_{k-1}\|^2 + \Gamma_k^*(s_k) + {h}^*(g_k)\\
\stackrel{\eqref{eq:Gamma-h}}{=}& \bar \varepsilon + \frac{1}{2\lam}(\|\hat x_{k-1}\|^2-\|\hat x_k\|^2).
\end{align*}

Replacing the index $k$ in the above inequality by $i$, summing the resulting inequality from $i=1$ to $k$, and using convexity and the definitions in \eqref{eq:bxk}, we obtain 
\begin{equation}\label{ineq:avg}
    \phi(\bar x_k) + f^*(\bar s_k) + h^*(\bar g_k)\le \bar \varepsilon + \frac{1}{2\lam k }\left(\|\hat x_0\|^2-\|\hat x_k\|^2\right),
\end{equation}
where $\bar g_k = (\sum_{i=1}^k g_i)/k$.

The above observation and \eqref{ineq:avg} together imply that
\begin{equation}\label{ineq:bar}
    \phi(\bar x_k) + f^*(\bar s_k) + h^*(\bar g_k) + \eta_k^*(-\bar g_k - \bar s_k) \le \bar \varepsilon.
\end{equation}

Noting from \eqref{eq:zeta} that $\hat h = h + \eta_k -\hat \eta_k$ and applying Theorem 4.17 of \cite{Beck2017} again, we obtain
\begin{align*}
    \hat h ^*(-\bar s_k) &= [(h + \eta_k)^* \square (-\hat \eta_k)^*](-\bar s_k)
= \min_{u\in \R^n}\{(h + \eta_k)^*(u) + (-\hat \eta_k)^*(-\bar s_k-u)\}\\
&\le (h + \eta_k)^*(-\bar s_k) + (-\hat \eta_k)^*(0).
\end{align*}

\begin{lemma}\label{lem:bound}
    Given $(\hat x_0,\bar \varepsilon) \in \R^n \times \R_{++}$, if $\lam \le 2d_0^2/\bar \varepsilon$ and $k \le 2d_0^2/(\lam \bar \varepsilon)$, then the sequences $\{\hat x_k\}$ and $\{\tx_k\}$ generated by PDPB$(\hat x_0,\lam, \bar \varepsilon)$ satisfy
    \begin{equation}\label{incl:xk}
        \hat x_k \in Q, \quad \tx_k \in Q.
    \end{equation}
\end{lemma}

Noticing that the objective function in \eqref{eq:xk} is $\lam^{-1}$-strongly convex, it thus follows from Theorem 5.25(b) of \cite{Beck2017} that for every $u \in \dom h$,
\begin{equation}\label{ineq:key}
    m_k + \frac{1}{2\lam} \|u-\hat x_{k}\|^2 \le \Gamma_k(u) + h(u) + \frac1{2\lam}\|u-\hat x_{k-1}\|^2 \le \phi(u)+ \frac1{2\lam}\|u-\hat x_{k-1}\|^2, 
\end{equation}
where the second inequality follows from the first one in Lemma \ref{ser-lemma1}(a).

Under the assumption that $\lam \le 2d_0^2/\bar \varepsilon$, using \eqref{ineq:xk}, the above inequality, and the triangle inequality, we have
\begin{align*}
    \|\hat x_k - \hat x_0\| &\le \|\hat x_k - x_0^*\| + \|x_0^* - \hat x_0\| \stackrel{\eqref{ineq:xk}}{\le} 4d_0, \\
    \|\tx_k - \hat x_0\| &\le \|\hat x_k - \hat x_0\| + \|\tx_k - \hat x_k\| \le 4d_0 + \sqrt{2\lam \bar \varepsilon} \le 6d_0.
\end{align*}
Hence, \eqref{incl:xk} follows immediately.

\begin{proposition}\label{prop:pdpb}
    Given $(\hat x_0,\bar \varepsilon) \in \R^n \times \R_{++}$, if $\lam \le 2d_0^2/\bar \varepsilon$, then the number of iterations for PDPB$(\hat x_0,\lam, \bar \varepsilon)$ to generate $(\bar x_k, \bar s_k)$ satisfying 
    \begin{equation}\label{ineq:pd}
        \hat \phi(\bar x_k) + f^*(\bar s_k) + \hat h^*(-\bar s_k) \le 10\bar \varepsilon
    \end{equation}
    is at most $2 d_0^2/(\lam \bar \varepsilon)$.
\end{proposition}

\begin{lemma}\label{lem:t1}
For $k \le 2d_0^2/(\lam \bar \varepsilon)$, we have
\begin{equation}\label{ineq:t1}
    t_{i_k} \le \bar{t}:= 4M(3d_0 + \lam M),
\end{equation}
where $i_k$ is the first iteration index in the cycle ${\cal C}_k$.
\end{lemma}

Using \eqref{ineq:f}, definitions of $m_j$ and $t_j$ in \eqref{eq:mj}, and the facts that $\tx_{i_k}=x_{i_k}$ and $\Gamma_{i_k}=\ell_f(\cdot;x_{k-1})$, we have
\begin{align}
    t_{i_k} &\stackrel{\eqref{eq:mj}}{=} \phi^\lam \left(\tx_{i_k}\right)-m_{i_k} = \phi^\lam (x_{i_k}) -m_{i_k} \nn \\
    &\stackrel{\eqref{eq:problem},\eqref{eq:phi-lam},\eqref{eq:mj}}{=} f(x_{i_k})-\ell_f(x_{i_k};\hat x_{k-1}) \stackrel{\eqref{ineq:f}}{\le} 2M\left\|x_{i_k}-\hat x_{k-1}\right\|, \label{ineq:tik}
\end{align}
where we have also used the definitions of $\phi$ and $\phi^\lam$ in \eqref{eq:problem} and \eqref{eq:phi-lam}, respectively, in the last identity.

\begin{lemma}\label{pds-lemma1}
Given $\hat x_0 \in \R^n$, for every $k \ge 1$ and $u \in \dom \hat h$, the sequence $\{\hat x_k\}$ generated by MPDS$(\hat x_0,\lam)$ satisfies
\begin{equation}\label{ineq:hat-phi-recur}
    \hat \phi(\hat x_k) - \ell_f(u;\hat x_{k-1}) - \hat h(u) \le 2\lam M^2 + \frac{1}{2\lam}\|u- \hat x_{k-1}\|^2 - \frac1{2\lam}\|u - \hat x_k\|^2.
\end{equation}
\end{lemma}

\begin{proof}
Noticing that the objective function in \eqref{eq:pds-1} is $\lam^{-1}$-strongly convex, it then follows from Theorem 5.25(b) of \cite{Beck2017} that for every $u \in \dom \hat h$,
\begin{equation}\label{ineq:ell-h-mk}
    \ell_f(u;\hat x_{k-1}) + \hat h(u) + \frac1{2\lam}\|u-\hat x_{k-1}\|^2 \ge m_k + \frac{1}{2\lam} \|u-\hat x_k\|^2,
\end{equation}
where $m_k = \ell_f(\hat x_k;\hat x_{k-1}) + \hat h(\hat x_k) + \|\hat x_k-\hat x_{k-1}\|^2/(2\lam)$.
Using \eqref{ineq:f} with $(x,y)=(\hat x_k,\hat x_{k-1})$, we have
\[
    \hat \phi(\hat x_k) - m_k = f(\hat x_k) - \ell_f(\hat x_k;\hat x_{k-1}) \stackrel{\eqref{ineq:f}}{\le} 2M\|\hat x_k - \hat x_{k-1}\| - \frac1{2\lam}\|\hat x_k-\hat x_{k-1}\|^2 \le 2\lam M^2,
\]
where the last inequality is due to Young's inequality $a^2+b^2\ge 2ab$.
Hence, \eqref{ineq:hat-phi-recur} follows from combining the above inequality and \eqref{ineq:ell-h-mk}.
\end{proof}

Noticing that the objective function in \eqref{eq:pds-1} is $\lam^{-1}$-strongly convex, it then follows from Theorem 5.25(b) of \cite{Beck2017} that for every $u \in \dom \hat h$,
\begin{equation}\label{ineq:ell-h-mk}
    \ell_f(u;\hat x_{k-1}) + \hat h(u) + \frac1{2\lam}\|u-\hat x_{k-1}\|^2 \ge m_k + \frac{1}{2\lam} \|u-\hat x_k\|^2,
\end{equation}
where $m_k = \ell_f(\hat x_k;\hat x_{k-1}) + \hat h(\hat x_k) + \|\hat x_k-\hat x_{k-1}\|^2/(2\lam)$.
